/**
 * Starter document for the dedicated canvas: one page and three objects
 * (image, shape, text) built with the `document` factories, so `/editor` has
 * something real to render on first load.
 *
 * The image is an inline PNG data URL (480x300, generated for this project) —
 * the same self-contained shape `src/lib/sourceResolver` produces, which keeps
 * the document serializable with no network access.
 */

import {
  createDocument,
  createImageObject,
  createPage,
  createShapeObject,
  createTextObject,
  type FremitDocument,
} from '@/lib/document';

export const STARTER_IMAGE_SRC = 'data:image/png;base64,';

export function createStarterDocument(): FremitDocument {
  const page = createPage({
    name: 'Poster',
    width: 1080,
    height: 1080,
    background: '#f5f0e8',
  });

  page.objects.push(
    createImageObject(STARTER_IMAGE_SRC, {
      name: 'Cover image',
      x: 90,
      y: 110,
      width: 900,
      height: 560,
      fit: 'cover',
    }),
    createShapeObject('rect', {
      name: 'Accent bar',
      x: 90,
      y: 730,
      width: 420,
      height: 26,
      cornerRadius: 13,
      fill: '#1f6feb',
    }),
    createTextObject('Fremit 1.0', {
      name: 'Headline',
      x: 90,
      y: 800,
      width: 900,
      height: 150,
      fontSize: 104,
      fontWeight: 700,
      fill: '#111111',
      align: 'left',
    }),
  );

  return createDocument([page]);
}
